 const items=rows.map(({p,e})=>{const values=reportValues(p,e,r).map((v,i)=>[8,9,10].includes(i)?Number(v).toFixed(2):v);return{values,red:e.payment==='เบิกจ่ายแล้ว',height:Math.max(46,...values.map((v,i)=>wrapped(measure,v,xs[i+1]-xs[i]-16).length*34+12))};});
