export const miniIcon=name=>{const p={open:'<path d="M7 17 17 7M7 7h10v10"/>',add:'<path d="M12 4v16M4 12h16"/>',edit:'<path d="m16 3 5 5M3 21l5-1L21 7l-5-5L3 15v6Z"/>',delete:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',archive:'<path d="M3 3h18v5H3zM5 8v13h14V8m-10 4h6"/>',import:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',export:'<path d="M12 15V3m-5 5 5-5 5 5M4 16v5h16v-5"/>'};return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]}</svg>`;};
export const isMasterUsed=(s,key,id)=>{const ref={contractors:'contractorId',supervisors:'supervisorId',workNames:'workNameId',workTypes:'workTypeId',workCodes:'workCodeId',budgetAccounts:'budgetAccountId'}[key];return [...(s.projects||[]),...(s.contractRegistry||[])].some(x=>x?.[ref]===id)||(key==='workTypes'&&(s.workNames||[]).some(x=>x.typeId===id))||(key==='workCodes'&&(s.workNames||[]).some(x=>x.codeIds?.includes(id)));};
