export async function readStore(){try{const db=await getDB();return await new Promise((resolve,reject)=>{const q=db.transaction('data').objectStore('data').get('workspace');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}catch{return memoryWorkspace?clone(memoryWorkspace):undefined;}}
