 for(let i=7;i<rows.length;i++){const cells=rows[i],r={workTypeId:'',finalPaymentDate:'',sourceRow:i+1,sourceSheet:sheet,warnings:[]};if(!cleanCell(cells[contractCol])&&!cleanCell(cells[fields.title]))continue;for(const [k,col]of Object.entries(fields))r[k]=col>=0?cells[col]??'':'';for(const k of ['contract','title','workCode','contractorRaw','unit','sourceId'])r[k]=cleanCell(r[k]);r.budgetAccount=cleanCell(r.budgetAccount).split(/\s+-\s+/)[0];for(const k of ['signedAt','start','end','deliveryDate','acceptanceDate','sourceExtendedEnd']){try{r[k]=parseG3Date(r[k]);}catch(e){r.warnings.push(k+': '+e.message);r[k]='';}}for(const k of ['duration','contractValue','actualCost','quantity','sourceExtensionDays']){if(r[k]===''||r[k]===null)r[k]='';else{const n=Number(String(r[k]).replace(/,/g,''));if(Number.isFinite(n))r[k]=n;else{r.warnings.push(k+' ไม่ใช่ตัวเลข');r[k]='';}}}const pm=cleanCell(r.paymentMonth).match(/^(\d{1,2})\/(\d{4})$/);r.paymentMonth=pm?String(+pm[2]>2400?+pm[2]-543:+pm[2])+'-'+pm[1].padStart(2,'0'):'';if(r.contractorRaw)r.warnings.push('รอจับคู่ผู้รับจ้าง');if(!r.contract)r.warnings.push('เลขสัญญาและข้อมูลสัญญายังว่างในต้นฉบับ');if(r.contractValue==='')r.warnings.push('PO ว่างในต้นฉบับ');if(r.paymentMonth)r.warnings.push('ต้นฉบับมีเพียงเดือนเบิกจ่าย ไม่ระบุวัน');if(r.sourceExtendedEnd)r.warnings.push('มีวันสิ้นสุดหลังขยายแยกจากสิ้นสุดสัญญา กรุณาตรวจหนังสือ');records.push(r);}
