 const text=`${item?.id||''} ${item?.title||''} ${item?.sourceTitle||''} ${item?.sourceFile||''} ${item?.sourceSheet||''}`;
 if(/PROVINCE|งบจังหวัด/i.test(text))return 'PROVINCE';
 if(/DOH|กรมทางหลวง|พรบ/i.test(text))return 'DOH';
 const snapFunding=Object.values(item?.snapshots||{})[0]?.funding;
