 if(cMatch){const y=+cMatch[1];return y<100?2500+y:y;}
 const snapYear=Object.values(item?.snapshots||{})[0]?.year;
 if(Number.isInteger(+snapYear)&&+snapYear>=2500)return +snapYear;
 const tMatch=String(`${item?.id||''} ${item?.title||''} ${item?.sourceTitle||''} ${item?.sourceFile||''}`).match(/(?:พ\.?ศ\.?\s*|พรบ\.?\s*|งบจังหวัด\s*|XLSX-(?:DOH|PROVINCE)-)(25\d{2}|\d{2})/);
