function bind(){bindSettings();$$('[data-dashboard-status]').forEach(b=>b.onclick=async()=>{try{await ensureScope();view='weekly';filter=b.dataset.dashboardStatus;page=1;query='';category='';render();window.scrollTo({top:0,behavior:'smooth'});}catch(e){toast(e.message,true);}});$('#discard-edits')?.addEventListener('click',()=>confirmAction('ยกเลิกค่าที่ค้างบันทึก','ค่าที่ค้างบนอุปกรณ์จะถูกล้าง กรุณาตรวจให้แน่ใจว่าไม่ต้องการส่งค่าเหล่านี้',()=>{editDrafts.clear();persistEdits();render();}));$$('[data-import-history-page]').forEach(b=>b.onclick=()=>{importHistoryPage=+b.dataset.importHistoryPage;render();});bindRegistry();bindArchive();$$('[data-amend-entry]').forEach(b=>b.onclick=()=>amendDialog(b.dataset.amendEntry));if($('#year'))$('#year').value=String(year);if($('#funding-select'))$('#funding-select').value=funding;bindCatalog();$$('[data-view]').forEach(b=>b.onclick=async()=>{view=b.dataset.view;filter='all';page=1;query='';category='';budgetFilter='';$('.sidebar').classList.remove('open');try{await ensureScope();if(view==='audit'&&cloudMode&&state.importHistory===undefined){const history=await cloud.loadHistoryCloud();if(history.revision!==state.revision)throw Error('ข้อมูลเปลี่ยนแปลงแล้ว กรุณาโหลดข้อมูลล่าสุดก่อนเปิดประวัติ');state.importHistory=history.importHistory||[];delete state.importHistoryDeferred;await cacheWorkspace(state);}await ensureFirstWeekly();render();}catch(e){toast(e.message,true);render();}});$$('[data-action]').forEach(b=>b.onclick=async()=>{try{await actions[b.dataset.action]?.();}catch(e){toast(e.message,true);}});$('#funding-select')?.addEventListener('change',async e=>{funding=e.target.value;budgetFilter='';page=1;try{await ensureScope();await ensureFirstWeekly();render();}catch(err){toast(err.message,true);render();}});$('#year')?.addEventListener('change',async e=>{year=+e.target.value;budgetFilter='';page=1;try{await ensureScope();await ensureFirstWeekly();render();}catch(err){toast(err.message,true);render();}});$('#report-select')?.addEventListener('change',async e=>{selected=e.target.value;page=1;try{await ensureScope(selected);render();}catch(err){toast(err.message,true);}});$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;page=1;render();});$('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;page=1;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});$('#category-filter')?.addEventListener('change',e=>{category=e.target.value;page=1;render();});$$('[data-page]').forEach(b=>b.onclick=()=>{page=+b.dataset.page;render();});$$('[data-edit]').forEach(b=>b.onclick=()=>projectDialog(b.dataset.edit));$$('[data-open-report]').forEach(b=>b.onclick=async()=>{const r=state.reports.find(x=>x.id===b.dataset.openReport);funding=r.funding||'DOH';year=r.year||year;try{await ensureScope(b.dataset.openReport);selected=b.dataset.openReport;view='weekly';filter='all';page=1;render();}catch(e){toast(e.message,true);render();}});$$('[data-entry]').forEach(input=>{const reportId=selected,id=input.closest('tr').dataset.id,k=input.dataset.entry,key=reportId+'|'+id+'|'+k;input.oninput=()=>{editDrafts.set(key,{reportId,id,k,value:input.type==='checkbox'?input.checked:input.value});persistEdits();updateSaveStatus();};input.onchange=()=>submitWeeklyEdit(reportId,id,k,input.type==='checkbox'?input.checked:['plan','weekly','actual'].includes(k)?+input.value:input.value);});$$('[data-quality-page]').forEach(b=>b.onclick=()=>{qualityPage=+b.dataset.qualityPage;render();});$('#retry-edits')?.addEventListener('click',async()=>{const failed=[...editDrafts.values()].filter(x=>x.error),first=failed[0];if(!first)return;const r=state.reports.find(x=>x.id===first.reportId);funding=r?.funding||funding;year=r?.year||year;try{await ensureScope(first.reportId);}catch(e){toast(e.message,true);render();return;}selected=first.reportId;view='weekly';filter='all';render();for(const x of failed.filter(x=>x.reportId===first.reportId))submitWeeklyEdit(x.reportId,x.id,x.k,['plan','weekly','actual'].includes(x.k)?+x.value:x.value);});}
async function submitWeeklyEdit(reportId,id,k,value){const key=reportId+'|'+id+'|'+k,token=uid();editDrafts.set(key,{reportId,id,k,value,token});persistEdits();try{await mutate('อัปเดตผลงาน '+id,s=>{const r=s.reports.find(x=>x.id===reportId);if(r.locked)throw Error('รายงานถูกปิดแล้ว');const e=r.entries[id];e[k]=value;if(k==='payment'){if(value==='เบิกจ่ายแล้ว'){e.paymentDate||=report().reference||today();e.note=paymentNote(e);}else{if(e.note?.startsWith('เบิกจ่ายแล้ว วันที่ '))e.note='';e.paymentDate='';}}if(k==='paymentDate'){if(!value)throw Error('กรุณาเลือกวันที่เบิกจ่าย');e.note=paymentNote(e);}const prev=previousEntry(r,id);if(k==='weekly')e.actual=+(Number(prev?.actual||0)+value).toFixed(2);if(k==='actual')e.weekly=+(value-Number(prev?.actual||0)).toFixed(2);validateDates(e);if(k!=='confirmed')e.confirmed=false;if(['weekly','actual','confirmed','payment','paymentDate'].includes(k))validateEntry(e,prev||{actual:0});else validateEntry(e);if(['payment','paymentDate','deliveryDate','acceptanceDate'].includes(k))syncContractDates(s,id,e,k==='payment'?['paymentDate']:[k]);});if(editDrafts.get(key)?.token===token)editDrafts.delete(key);persistEdits();restoreEdits();}catch(e){if(editDrafts.get(key)?.token===token)editDrafts.get(key).error=e.message;persistEdits();toast(e.message,true);restoreEdits();}}
function bindSettings(){$('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{let logo='';const file=$('#logo-file').files?.[0];if(file){if(file.type!=='image/png'||file.size>500000)throw Error('เลือก PNG ขนาดไม่เกิน 500 KB');logo=await readPNG(file);}const saveSettings=()=>mutate('แก้ไขรูปแบบรายงาน',s=>{s.settings.organization=f.get('organization');s.settings.reportTitles={DOH:f.get('titleDOH').trim(),PROVINCE:f.get('titleProvince').trim()};s.settings.title=s.settings.reportTitles.DOH;s.settings.systemName=String(f.get('systemName')).trim();if(f.get('removeLogo'))s.settings.logo='';if(logo)s.settings.logo=logo;});if(f.get('removeLogo'))confirmAction('ยืนยันลบโลโก้','ลบโลโก้ปัจจุบันออกจากระบบและบันทึกการตั้งค่านี้',saveSettings);else await saveSettings();}catch(err){toast(err.message,true);}});$('#cloud-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;const f=new FormData(e.target);try{cloud.setConfig(f.get('url'),f.get('key'));const data=await loadWorkspace();if(data){validateLoadedWorkspace(data);state=data;selected=state.reports[0].id;year=state.years[0];await cacheWorkspace(state);cloudMode=true;render();toast('โหลดข้อมูลจาก Supabase แล้ว ไม่ต้องเข้าสู่ระบบ');}else{state.revision=0;cloudMode=true;render();toast('เชื่อมต่อแล้ว ฐานข้อมูลยังว่าง กดนำเข้าข้อมูล JSON เพื่อเริ่มใช้งาน');}}catch(err){toast(err.message,true);}finally{b.disabled=false;}});}
const catalogManager=catalogUI({getState:()=>state,esc,mutate,modal,field,buttons,selectField,render,toast,confirmAction,addYear:()=>actions['new-year']()});
function catalog(){return header('ข้อมูลพื้นฐาน','ทะเบียนกลางสำหรับเลือกใช้ในทุกสัญญาและทุกปีงบประมาณ')+catalogManager.html();}
function bindCatalog(){catalogManager.bind();}
async function loadWorkspace(scope){const data=await cloud.loadCloud(scope||{funding,year});if(data)data.importHistoryDeferred=true;if(data&&!data.contractors){normalizeState(data);const result=await cloud.saveCloud(data,data.revision||0);data.revision=result.revision;}return data;}
function weekLabel(r){if(/^สัปดาห์ที่/.test(r.title))return r.title;const n=r.title.match(/(?:รอบที่|สัปดาห์ที่)\s*(\d+)/);return 'สัปดาห์ที่ '+(n?.[1]||state.reports.filter(x=>(!x.year||x.year===year)&&(!x.funding||x.funding===funding)).slice().sort((a,b)=>(a.end||'').localeCompare(b.end||'')).findIndex(x=>x.id===r.id)+1);}
function applyBrand(){document.title=state.settings.systemName;$('#system-name').textContent=state.settings.systemName;const logo=$('.brand .logo');logo.classList.toggle('uploaded-logo',!!state.settings.logo);logo.innerHTML=state.settings.logo?'<img alt="โลโก้" src="'+state.settings.logo+'">':'P<span>n</span>';let icon=document.querySelector('link[rel=icon]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.append(icon);}icon.href=state.settings.logo||'data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#145744"/><text x="13" y="44" font-size="36" fill="white">P</text></svg>');document.querySelector('footer').textContent=state.settings.systemName+' · '+state.settings.organization;}
function readPNG(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas');const scale=Math.min(1,256/img.width,256/img.height);c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/png'));};img.onerror=()=>reject(Error('อ่านภาพ PNG ไม่สำเร็จ'));img.src=reader.result;};reader.onerror=()=>reject(Error('อ่านไฟล์ไม่ได้'));reader.readAsDataURL(file);});}
function amendDialog(pid){const r=report(),rows=activeRows();if(!rows.length)return toast('ไม่มีรายการให้แก้ไข',true);pid||=rows[0].p.id;const e=entryFor(r,pid),prev=previousEntry(r,pid)||{actual:0};modal('แก้ไขรายงานย้อนหลัง · '+weekLabel(r),`<form id="amend-form"><div class="notice">แก้ข้อมูลแล้วกดบันทึกได้ทันที ประวัติจะเก็บให้อัตโนมัติ</div>${selectField('สัญญาที่ต้องการแก้ไข','contractId',rows.map(x=>({value:x.p.id,label:x.p.contract+' · '+x.p.title})),pid)}<div class="form-grid">${field('แผนงานสะสม (%)','plan',e.plan,'number','min="0" max="100" step="0.01" required')}${field('ผลงานรายสัปดาห์ (%)','weekly',e.weekly,'number','min="0" max="100" step="0.01" required')}${field('ผลงานสะสม (%)','actual',e.actual,'number','min="0" max="100" step="0.01" required')}${selectField('สถานะเบิกจ่าย','payment',['รอส่งมอบงาน','รอเบิกจ่าย','เบิกจ่ายแล้ว'],e.payment)}${field('วันที่ส่งมอบงาน','deliveryDate',e.deliveryDate||'','date')}${field('วันที่ตรวจรับงาน','acceptanceDate',e.acceptanceDate||'','date')}${field('วันที่เบิกจ่าย','paymentDate',e.paymentDate||parsePaymentDate(e.note),'date')}${field('หมายเหตุ','note',e.note,'textarea')}</div><p class="form-error" role="alert"></p>${buttons('บันทึกการแก้ไข')}</form>`,async f=>{const patch={};for(const k of ['plan','weekly','actual','note','payment','paymentDate','deliveryDate','acceptanceDate']){const v=['plan','weekly','actual'].includes(k)?+f.get(k):String(f.get(k)||'');const original=k==='paymentDate'?e.paymentDate||parsePaymentDate(e.note):e[k]??'';if(v!==original)patch[k]=v;}
 if(!Object.keys(patch).length)throw Error('ยังไม่มีข้อมูลเปลี่ยนแปลง');await saveAmendment(r.id,{[pid]:patch});});const form=$('#amend-form');form.addEventListener('input',ev=>{if(ev.target!==form.elements.contractId)form.elements.contractId.disabled=true;});form.elements.contractId.value=pid;form.elements.contractId.onchange=()=>amendDialog(form.elements.contractId.value);form.elements.payment.value=e.payment;
 form.elements.weekly.oninput=()=>{form.elements.actual.value=+(Number(prev.actual)+Number(form.elements.weekly.value)).toFixed(2);};form.elements.actual.oninput=()=>{form.elements.weekly.value=+(Number(form.elements.actual.value)-Number(prev.actual)).toFixed(2);};form.elements.payment.onchange=()=>{if(form.elements.payment.value==='เบิกจ่ายแล้ว'&&!form.elements.paymentDate.value)form.elements.paymentDate.value=r.reference||today();updateNote();};const updateNote=()=>{if(form.elements.payment.value==='เบิกจ่ายแล้ว'&&form.elements.paymentDate.value)form.elements.note.value=paymentNote({payment:'เบิกจ่ายแล้ว',paymentDate:form.elements.paymentDate.value});};form.elements.paymentDate.onchange=updateNote;
}
function showFormError(form,message,input){let el=form.querySelector('.form-error');if(!el){el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');form.append(el);}el.id='active-form-error';el.textContent=message;const target=input||form.querySelector('input:not([type=hidden]),select,textarea');target?.setAttribute('aria-describedby',el.id);if(input)input.setAttribute('aria-invalid','true');target?.focus();toast(message,true);}
function saveAmendment(id,patch){return enqueueSave(()=>runAmendment(id,patch));}
async function runAmendment(id,patch){busy=true;try{if(!cloudMode&&cloud.config())throw Error('ยังไม่เชื่อมต่อฐานข้อมูล กรุณาโหลดข้อมูลล่าสุดก่อนบันทึก');let next;if(cloudMode){const result=await cloud.amendCloud(id,patch,state.revision||0);next=result.document;}else{next=amendReport(state,id,patch);next.revision=(state.revision||0)+1;}normalizeState(next);try{await cacheWorkspace(next);}catch(e){if(!cloudMode)throw e;toast('บันทึกบน Supabase แล้ว แต่สำรองบนอุปกรณ์ไม่สำเร็จ',true);}state=next;render();toast('บันทึกการแก้ไขย้อนหลังแล้ว');}finally{busy=false;}}
